import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Fused Mish-Mish CUDA kernel
mish_mish_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void mish_mish_kernel(const float* input, float* output, int num_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        float x = input[idx];
        // First Mish
        float sp = logf(1.0f + expf(x));
        float mish1 = x * tanhf(sp);
        // Second Mish
        float sp2 = logf(1.0f + expf(mish1));
        output[idx] = mish1 * tanhf(sp2);
    }
}

torch::Tensor mish_mish_cuda(torch::Tensor input) {
    auto output = torch::empty_like(input);
    int num_elements = input.numel();
    const int block_size = 256;
    dim3 grid((num_elements + block_size - 1) / block_size);

    mish_mish_kernel<<<grid, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        num_elements
    );
    return output;
}
"""

mish_mish_cpp = "torch::Tensor mish_mish_cuda(torch::Tensor input);"

mish_mish = load_inline(
    name="mish_mish",
    cpp_sources=mish_mish_cpp,
    cuda_sources=mish_mish_source,
    functions=["mish_mish_cuda"],
    verbose=True,
    extra_cuda_cflags=["-O2"]
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size, padding=kernel_size//2)
        self.mish_mish = mish_mish

    def forward(self, x):
        x = self.conv(x)
        x = self.mish_mish.mish_mish_cuda(x)
        return x
